// The written reading — Evelyn's prose, generated by Claude.
//
// Everything factual (the initials, the seven cards, her numbers, her stone) is
// computed upstream and passed in; the model only turns those facts into
// Evelyn's voice. It is never asked to invent an initial or name a card
// (spec §2 steps 6–7). One retry per call; throws on an empty/truncated reply
// so the caller never ships a blank section.

import Anthropic from '@anthropic-ai/sdk';
import { anthropicFailover } from '../anthropicWithFailover';
import type { ReadingNumbers } from './numbers';
import type { ResolvedInitials } from './initials';
import type { DrawnCard } from './draw';

// Routes through anthropicFailover (same as chat/greetings/emails): multi-key
// failover + the central per-model "thinking off" injection, so Sonnet 5.5 runs
// without burning its 4096-token budget on a thinking block. Pinned to a known
// model for this paid deliverable rather than tracking the admin config.
const MODEL = 'claude-sonnet-5-5';
const MAX_TOKENS = 4096;

// Evelyn's voice + the compliance fences, shared by every call (spec §2 step 9).
const EVELYN_SYSTEM = `You are Evelyn Cross, a warm, perceptive spiritual reader writing a private reading for one woman. You write in flowing second-person prose ("you"), intimate and grounded, never breathless. You are specific and sensory, never generic horoscope filler.

Hard rules you never break:
- Write ONLY prose. No headings, no bullet lists, no numbered lists, no markdown, no stage directions.
- State any card names and initials EXACTLY as given to you. Never invent, change, or add an initial or a card.
- Speak in tendencies and energies ("tends to", "is drawn toward", "often"), NEVER guarantees or promises of outcome, dates, pregnancy, marriage, money, or health.
- Give no medical, legal, or financial advice.
- Do not describe the mechanics of the cards or quote textbook meanings; weave the feeling of each card into her life.
- This is for entertainment and reflection. Never claim certainty about a real, identifiable person.`;

async function write(system: string, user: string): Promise<string> {
  for (let attempt = 1; attempt <= 2; attempt++) {
    const res = await anthropicFailover.messages.create({
      model: MODEL,
      max_tokens: MAX_TOKENS,
      system,
      messages: [{ role: 'user', content: user }],
    });
    const text = res.content
      .filter((b): b is Anthropic.TextBlock => b.type === 'text')
      .map((b) => b.text)
      .join('')
      .trim();
    if (text.length > 0 && res.stop_reason !== 'max_tokens') return text;
    if (text.length > 400) return text; // usable even if it ran long
    if (attempt === 2) {
      throw new Error(`Reading section came back empty/truncated after 2 attempts (stop_reason=${res.stop_reason}).`);
    }
  }
  throw new Error('unreachable');
}

export interface ReadingProse {
  reading: string; // the seven-card Soulmate Initials reading
  portrait: string; // 1,000+ word soulmate portrait
  heartBlock: string; // bonus 1
  pastLove: string; // bonus 2
  stonePage: string | null; // only when the add-on was bought
}

function factsBlock(args: {
  firstName: string;
  stone: string;
  numbers: ReadingNumbers;
  initials: ResolvedInitials;
  draw: DrawnCard[];
}): string {
  const cards = args.draw
    .map((d) => `  ${d.position}. "${d.question}" — ${d.card}`)
    .join('\n');
  return `Her name: ${args.firstName}
Her stone: ${args.stone}
Her numbers: Life Path ${args.numbers.lifePath}, First-Name number ${args.numbers.firstNameNumber}, Personal Year ${args.numbers.personalYear}
Her soulmate's first initial: ${args.initials.first}
Her soulmate's last initial: ${args.initials.last}
Her seven cards (position → card):
${cards}`;
}

/** Generate every prose section for one order. */
export async function generateProse(args: {
  firstName: string;
  stone: string;
  bump: boolean;
  numbers: ReadingNumbers;
  initials: ResolvedInitials;
  draw: DrawnCard[];
}): Promise<ReadingProse> {
  const facts = factsBlock(args);

  const reading = await write(
    EVELYN_SYSTEM,
    `Write ${args.firstName}'s Soulmate Initials Reading as one flowing letter (about 700–900 words). Move through her seven cards in order, letting each answer its question as part of the story — who he is, that his first initial is ${args.initials.first} and his last initial is ${args.initials.last} (state both initials plainly and warmly), whether he is someone new or someone she already knows, where they are likely to meet, when, and what he is like and looks like. Connect the cards to each other so it reads as one unfolding picture, not seven separate notes. Open by greeting her by name.

${facts}`,
  );

  const portrait = await write(
    EVELYN_SYSTEM,
    `Write a Soulmate Portrait of the man described by ${args.firstName}'s reading — AT LEAST 1,000 words of flowing prose. Draw on her seven cards and her numbers. Cover his personality, his strengths and his flaws, how he shows love, how he handles conflict, what he is drawn to, and how he will likely feel to be around. Keep his initials consistent (${args.initials.first} and ${args.initials.last}). Tendencies, never guarantees.

${facts}`,
  );

  const heartBlock = await write(
    EVELYN_SYSTEM,
    `Write ${args.firstName}'s Heart Block Reading (about 450–600 words of flowing prose): what has quietly been keeping love at arm's length for her, where it likely comes from, and gentle, concrete ways she can begin to loosen it. Ground it in her cards and numbers. Compassionate, never clinical; no therapy or medical framing.

${facts}`,
  );

  const pastLove = await write(
    EVELYN_SYSTEM,
    `Write ${args.firstName}'s Past Love Reading (about 450–600 words of flowing prose): whether someone from her past is likely circling back, what that connection still holds, and whether leaning back toward him tends to serve her or hold her. Tendencies and energies, never a prediction of what will happen.

${facts}`,
  );

  const stonePage = args.bump
    ? `Tonight, under the moon, your ${args.stone} will be charged and sealed into this reading — a small, steady anchor for everything these pages have named. Keep it close in the days ahead. When your mind races toward him, hold it, breathe once, and let it bring you back to yourself. It is not a promise. It is a reminder that you are already becoming the woman this reading is written for.`
    : null;

  return { reading, portrait, heartBlock, pastLove, stonePage };
}
